exercises.starter_code:
#include <stdio.h>

int main(void) {
    // wrap disk full
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void) {
    char msg[64];
    snprintf(msg, sizeof msg, "reading %s: %s", "data.txt", "disk full");
    puts(msg);
    puts("Disk is full");
    return 0;
}
